// Heuristic classification + id_number
const text = ($json.text || '').toLowerCase();
const job_id = $json.job_id || ("jb_" + Date.now());
const bins = [
  {bin:'CONTRACT',   kw:['loan agreement','governing law','borrower','lender']},
  {bin:'BANKING',    kw:['void cheque','transit','institution','account number','bank statement']},
  {bin:'CARFAX',     kw:['carfax','vehicle history','odometer','accident']},
  {bin:'DEALER BOS', kw:['bill of sale','sale price','dealer','purchase price']},
  {bin:'INSURANCE',  kw:['policy','binder','coverage','deductible','insured']},
  {bin:'PPSA',       kw:['ppsa','financing statement','registration']},
  {bin:'UCC',        kw:['ucc','filing number','secured party']},
  {bin:'OWNERSHIP',  kw:['certificate of title','plate','owner']} 
];
let best='MISC', score=0;
for (const b of bins){ const s=b.kw.reduce((c,k)=>c+(text.includes(k)?1:0),0); if(s>score){score=s;best=b.bin;} }
const idnum = ( ($json.text||'').match(/\b(?:agreement|contract)\s*(?:no\.?|number|#)\s*[:\-]?\s*([A-Z0-9\-\/]+)/i)?.[1] || '' ).trim();
return [{ json: { job_id, bin: score?best:'UNASGD FAX', confidence: score? Math.min(1, 0.3 + score*0.15):0.1, id_number:idnum } }];

// Build response with file_url
const fileId = $items(1)[0].json.id; // from Drive_Upload
const fileUrl = `https://drive.google.com/uc?id=${fileId}`;
const out = { ...$json, file_url: fileUrl };
return [{ json: out }];
